const readingField=section=>section?.content?`<div class="reading-content"><p>${esc(section.content)}</p>${section.signals?.length?`<ul>${section.signals.map(signal=>`<li>${esc(signal)}</li>`).join("")}</ul>`:""}</div>`:`<div class="reading-missing"><strong>N/D</strong><span>Sezione da compilare con dati verificati.</span></div>`;
function readingFixtureLink(match,teams,reading,prediction,history){
  const home=teams.find(team=>team.id===match.homeTeam),away=teams.find(team=>team.id===match.awayTeam);
  const likelyScore=prediction?.exactScores?.[0]?.score;
  const preview=prediction?`<span class="reading-fixture-preview" aria-label="Anteprima della lettura"><span><small>Verdetto</small><strong>${esc(prediction.verdict.label)}</strong></span><span><small>Risultato</small><strong>${esc(likelyScore||"N/D")}</strong></span><span><small>Confidenza</small><strong>${prediction.confidence.value}/100</strong></span></span>`:reading?.summary?`<span class="reading-fixture-preview reading-fixture-preview-text"><span><small>Anteprima</small><strong>${esc(reading.summary)}</strong></span></span>`:"";
  const historyState=history?`<span class="reading-fixture-history ${history.coverage.available<5?"is-limited":""}">Precedenti ${history.coverage.available}/5</span>`:"";
  return `<a class="reading-fixture" href="lettura.html?match=${esc(match.id)}"><span class="reading-fixture-meta">Giornata ${match.matchday} · ${scheduleLabel(match)}</span><span class="reading-fixture-teams">${teamLogo(home)}<b>VS</b>${teamLogo(away)}</span>${preview}<span class="reading-fixture-state ${prediction?"prediction-ready":reading?.status||"structure"}">${prediction?`Pronostico preliminare · sorpresa ${prediction.surprise.value}/100`:reading?.status==="published"?"Pubblicata":reading?.status==="draft"?"Bozza":"Struttura pronta"}</span>${historyState}</a>`;
}
function readingIndex(readings,matches,teams,predictions=[],headToHeadData){
  const scheduled=matches.filter(match=>match.competition==="serie-a"&&match.status!=="finished").sort((a,b)=>a.matchday-b.matchday||String(a.date||a.matchdayDate).localeCompare(String(b.date||b.matchdayDate)));
  const nextDay=scheduled[0]?.matchday,nextMatches=scheduled.filter(match=>match.matchday===nextDay),byMatch=new Map(readings.map(reading=>[reading.matchId,reading])),predictionByMatch=new Map(predictions.map(prediction=>[prediction.matchId,prediction])),historyByMatch=new Map((headToHeadData?.fixtures||[]).map(fixture=>[fixture.fixtureId,fixture]));
  const firstLeg=scheduled.filter(match=>match.matchday<=19),matchdays=[...new Set(firstLeg.map(match=>match.matchday))];
  const directory=matchdays.map(matchday=>`<details class="reading-h2h-matchday"${matchday===nextDay?" open":""}><summary><span>Giornata ${matchday}</span><small>10 partite · storico H2H collegato</small></summary><div class="reading-fixture-grid">${firstLeg.filter(match=>match.matchday===matchday).map(match=>readingFixtureLink(match,teams,byMatch.get(match.id),predictionByMatch.get(match.id),historyByMatch.get(match.id))).join("")}</div></details>`).join("");
  return hero("Analisi prepartita","Letture","Il modello stima prima le probabilità da storico, rendimento e matchup tattico. Le quote vengono confrontate soltanto dopo, per misurare prezzo ed eventuale valore.")+`<section class="section"><header class="section-heading"><div><p class="eyebrow">Prossimo turno</p><h2>Giornata ${nextDay||"N/D"}</h2></div><p>Apri una partita per probabilità, quote eque, scenari e mercati disponibili.</p></header>${nextMatches.length?`<div class="reading-fixture-grid">${nextMatches.map(match=>readingFixtureLink(match,teams,byMatch.get(match.id),predictionByMatch.get(match.id),historyByMatch.get(match.id))).join("")}</div>`:empty("Nessuna partita programmata.")}</section><section class="section reading-h2h-directory"><header class="section-heading"><div><p class="eyebrow">Girone d'andata completo</p><h2>Precedenti per tutte le 190 partite</h2></div><p>Apri una giornata e poi la singola lettura per marcatori e ammoniti degli ultimi cinque confronti disponibili.</p></header><div class="reading-h2h-matchdays">${directory}</div></section>`;
}
function readingDetail(match,reading,teams){
  const home=teams.find(team=>team.id===match.homeTeam),away=teams.find(team=>team.id===match.awayTeam),sections=reading?.sections||{},completed=readingModules.filter(([key])=>sections[key]?.content).length;
  const title=reading?.title||`${home.name} - ${away.name}`;
  return `<nav class="reading-back"><a href="lettura.html">← Tutte le letture</a><a href="calendario.html#giornata-${match.matchday}">Giornata ${match.matchday}</a></nav><section class="reading-match-hero"><div><p class="eyebrow">Serie A · Giornata ${match.matchday}</p><h1>${esc(title)}</h1><p>${scheduleLabel(match)}</p><span class="reading-progress">${completed}/7 sezioni compilate</span></div><div class="reading-matchup">${teamLogo(home)}<b>VS</b>${teamLogo(away)}</div></section>${reading?.summary?`<aside class="reading-summary"><span>Sintesi editoriale</span><p>${esc(reading.summary)}</p></aside>`:""}<section class="section reading-detail"><header class="section-heading"><div><p class="eyebrow">Scheda di lavoro</p><h2>Struttura della lettura</h2></div><p>I campi non ancora verificati restano N/D.</p></header><div class="reading-module-grid">${readingModules.map(([key,number,moduleTitle,description])=>`<article class="reading-module" id="lettura-${key}"><header><span>${number}</span><div><h3>${moduleTitle}</h3><p>${description}</p></div></header>${readingField(sections[key])}${sections[key]?.sources?.length?`<footer>${sections[key].sources.map(source=>`<a href="${esc(source.url)}" target="_blank" rel="noreferrer">${esc(source.label||"Fonte")}</a>`).join(" · ")}</footer>`:""}</article>`).join("")}</div></section>`;
}
function headToHeadPanel(history,prediction){
  if(!history)return `<section class="section reading-h2h-section"><aside class="data-warning"><strong>Precedenti N/D</strong><p>Nessun dataset storico collegato a questa partita.</p></aside></section>`;
  const meetings=history.previousMeetings||[],available=history.coverage?.available??meetings.length;
  const eventList=(items,emptyLabel)=>items?.length?`<ul>${items.map(item=>`<li><strong>${esc(item.player)}</strong><small>${esc(item.team)} · ${esc(item.minute||"minuto N/D")}${item.ownGoal?" · autogol":""}</small></li>`).join("")}</ul>`:`<p class="reading-h2h-empty">${emptyLabel}</p>`;
  const cards=meeting=>{const gap=meeting.coverage?.missingFields?.includes("bookingEvents");if(!meeting.bookings?.length)return `<p class="reading-h2h-empty">${gap?"Dettaglio ammoniti N/D":"Nessun ammonito registrato"}</p>`;return `${eventList(meeting.bookings,"Nessun ammonito registrato")}${gap?'<small class="reading-h2h-warning">Conteggio ESPN non riconciliato: sono mostrati soltanto gli eventi nominativi disponibili.</small>':""}`};
  const goals=meeting=>{const gap=meeting.coverage?.missingFields?.includes("goalEvents");if(!meeting.goals?.length)return `<p class="reading-h2h-empty">${gap?"Dettaglio marcatori N/D":"Nessun gol"}</p>`;return eventList(meeting.goals,"Nessun gol")};
  const rows=meetings.map((meeting,index)=>`<details class="reading-h2h-match"${index===0?" open":""}><summary><span>${dateOnly(meeting.date)} · ${esc(meeting.competition)}</span><strong>${esc(meeting.homeTeam.name)} ${meeting.score.home}-${meeting.score.away} ${esc(meeting.awayTeam.name)}</strong></summary><div class="reading-h2h-events"><section><h3>Marcatori</h3>${goals(meeting)}</section><section><h3>Ammoniti</h3>${cards(meeting)}</section></div><a href="${esc(meeting.source.url)}" target="_blank" rel="noreferrer">Fonte ESPN</a></details>`).join("");
  const model=prediction?.headToHead?.usedInModel?`<aside class="reading-h2h-model"><strong>Uso nel modello</strong><p>Correttivo leggero sui gol attesi: fattore casa ${prediction.headToHead.home.toFixed(3)}, fattore ospite ${prediction.headToHead.away.toFixed(3)}. L'effetto è limitato al 5% per lato e non sostituisce forma, rendimento o matchup tattico.</p></aside>`:"";
  return `<section class="section reading-h2h-section"><header class="section-heading"><div><p class="eyebrow">Storico ufficiale · ESPN</p><h2>Ultimi ${available} scontri diretti disponibili</h2></div><p>${available}/5 precedenti · Serie A, Serie B e Coppa Italia</p></header>${available<5?`<aside class="data-warning"><strong>Campione storico limitato</strong><p>Il provider espone ${available} confronti per questa coppia; quelli mancanti non vengono ricostruiti.</p></aside>`:""}<div class="reading-h2h-list">${rows}</div>${model}</section>`;
}
const sampleLabel=matches=>matches<5?"Campione insufficiente":matches<10?"Indicazione moderata":"Confronto più significativo";
