  const banner=document.querySelector(".reading-prototype-banner p");if(banner)banner.textContent="La scheda include ora le probabili formazioni indicate dalla fonte editoriale; indisponibilità e scelte definitive restano da verificare vicino alla partita.";
  document.querySelectorAll(".reading-picks li").forEach(item=>{if(item.textContent.includes("Rose e sistemi"))item.textContent="Rose, sistemi e probabili formazioni";if(item.textContent.includes("Le formazioni probabili"))item.textContent="Le probabili formazioni sono proiezioni editoriali e vanno riconfermate vicino alla partita."});
  if(!prediction){const summary=document.querySelector(".reading-summary-prototype");if(summary)summary.innerHTML='<div class="reading-exact-scores"><span>Risultati esatti probabili</span><div class="reading-score-list"><div><strong>N/D</strong><small>Alternativa</small></div><div class="is-central"><strong>N/D</strong><small>Centrale</small></div><div><strong>N/D</strong><small>Alternativa</small></div></div></div><div class="reading-final-verdict"><span>Verdetto finale</span><strong>In preparazione</strong><small>Nessuna previsione senza dati sufficienti</small></div>';}
